-- The deals pipeline's venue list (Ben, 6 Oct 2026: "Ubud has close to a thousand restaurants;
-- we need to work all of them, know their specials and never lose track").
-- One row per restaurant, café, warung, bar, spa and yoga studio in Ubud. Status is derived, never
-- stored (src/lib/deals/pipeline.ts): not checked → special found → venue confirmed → live → reconfirm due,
-- plus "checked, nothing found" and "closed".
-- Sources: OpenStreetMap (Overpass, data as of 24 Jul 2026, bbox -8.565,115.215 to -8.455,115.315),
-- the 31 venues already here, and venues named in the 5–6 Oct research. List and builder:
-- Code/handovers/ubudian-deals-tools/venues-2026-10-06.json (build-venues.py beside it).
-- Expected: 964 rows inserted, 20 existing rows given a map pin and category; nothing deleted.

ALTER TABLE deal_venues ADD COLUMN IF NOT EXISTS category text CHECK (category IS NULL OR category IN ('restaurant','warung','cafe','bar','spa','yoga'));
ALTER TABLE deal_venues ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual','osm','research','venue'));
ALTER TABLE deal_venues ADD COLUMN IF NOT EXISTS osm_id text;
ALTER TABLE deal_venues ADD COLUMN IF NOT EXISTS lat double precision;
ALTER TABLE deal_venues ADD COLUMN IF NOT EXISTS lng double precision;
-- When we last looked for a special (researched_at already records it) and when to look again.
ALTER TABLE deal_venues ADD COLUMN IF NOT EXISTS next_check_on date;
-- Set when a check finds the venue has closed; the row stays so it is never re-added.
ALTER TABLE deal_venues ADD COLUMN IF NOT EXISTS closed_at timestamptz;
CREATE UNIQUE INDEX IF NOT EXISTS deal_venues_osm_key ON deal_venues (osm_id) WHERE osm_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS deal_venues_check_idx ON deal_venues (next_check_on NULLS FIRST, researched_at NULLS FIRST);

-- The nightly scout (src/lib/deals/scout.ts) stores what it finds as hidden specials, source 'scout',
-- with its private one-line reason (the saving, or why it fails the rule). Never rendered publicly.
ALTER TABLE specials DROP CONSTRAINT IF EXISTS specials_source_check;
ALTER TABLE specials ADD CONSTRAINT specials_source_check CHECK (source IN ('form', 'seed', 'whatsapp', 'instagram', 'admin', 'scout'));
ALTER TABLE specials ADD COLUMN IF NOT EXISTS research_note text;

